declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
$user=app_require_permission('wholesale.view');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Wholesale Customer 360</title><style>
:root{--bg:#f2f1ed;--panel:#fff;--ink:#171815;--muted:#6a716b;--line:#deded8;--accent:#d94a2b;--good:#157347;--warn:#9b6400}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}.top{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 22px;background:#fff;border-bottom:1px solid var(--line)}.top a,.btn{display:inline-flex;align-items:center;min-height:38px;padding:8px 11px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--ink);font-size:10px;font-weight:850;text-decoration:none;cursor:pointer}.shell{max-width:1500px;margin:auto;padding:24px}.head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:15px}.eyebrow{font-size:9px;font-weight:950;text-transform:uppercase;letter-spacing:.12em;color:var(--accent)}h1{margin:5px 0;font-size:38px;letter-spacing:-.05em}.muted{color:var(--muted);font-size:10px;line-height:1.5}.layout{display:grid;grid-template-columns:340px minmax(0,1fr);gap:12px}.panel{background:#fff;border:1px solid var(--line);border-radius:15px;padding:14px}.accounts{display:grid;gap:7px;max-height:calc(100vh - 190px);overflow:auto}.account{padding:12px;border:1px solid var(--line);border-radius:11px;background:#fff;cursor:pointer;text-align:left}.account.active{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent)}.account strong{display:block;font-size:11px}.chips{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}.chip{padding:4px 6px;border-radius:999px;background:#f0efeb;font-size:8px;font-weight:900}.chip.good{background:#eaf7ef;color:var(--good)}.chip.warn{background:#fff2d9;color:var(--warn)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:10px}.stat{padding:13px;border:1px solid var(--line);border-radius:12px;background:#fff}.stat small{font-size:8px;text-transform:uppercase;color:var(--muted);font-weight:900}.stat strong{display:block;font-size:22px;margin-top:5px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.section{border:1px solid var(--line);border-radius:13px;padding:13px;background:#fff}.section h2{font-size:13px;margin:0 0 4px}.list{display:grid;gap:7px;margin-top:9px}.row{padding:9px;border:1px solid var(--line);border-radius:9px}.rowtop{display:flex;justify-content:space-between;gap:8px}.row strong{font-size:10px}.row small{font-size:8px;color:var(--muted)}.money{font-size:13px!important}.empty{padding:20px;text-align:center;color:var(--muted);font-size:10px;border:1px dashed #ccc;border-radius:10px}.search{width:100%;min-height:38px;border:1px solid var(--line);border-radius:9px;padding:8px 10px;margin-bottom:9px}@media(max-width:980px){.layout{grid-template-columns:1fr}.accounts{max-height:none}.stats,.grid{grid-template-columns:1fr 1fr}}@media(max-width:620px){.stats,.grid{grid-template-columns:1fr}}
</style></head><body><header class="top"><strong>Wholesale Customer 360</strong><div><a href="wholesale-accounts.php">Accounts</a> <a href="wholesale-fulfillment.php">Fulfillment</a> <a href="wholesale-receivables.php">A/R</a></div></header><main class="shell"><div class="head"><div><div class="eyebrow">W5 portal + operations</div><h1>Customer relationship, operations and money.</h1><p class="muted">One internal view of the customer account, live fulfillment, requests, receivables, catalog context, and relationship history.</p></div><button class="btn" id="refresh">Refresh</button></div><div class="layout"><aside class="panel"><input class="search" id="search" placeholder="Search wholesale customers"><div class="accounts" id="accounts"></div></aside><section id="detail"><div class="panel empty">Choose a wholesale customer account.</div></section></div></main><script>
(()=>{const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>'$'+Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});let rows=[],active='';async function api(u){const r=await fetch(u,{cache:'no-store',headers:{Accept:'application/json'}}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed');return d}function renderList(){const q=$('search').value.trim().toLowerCase(),list=rows.filter(a=>!q||[a.business_name,a.primary_email,a.account_status].join(' ').toLowerCase().includes(q));$('accounts').innerHTML=list.length?list.map(a=>`<button class="account ${a.public_id===active?'active':''}" data-id="${esc(a.public_id)}"><strong>${esc(a.business_name)}</strong><div class="muted">${esc(a.primary_email||'No email')} · ${esc(a.payment_terms||'No terms')}</div><div class="chips"><span class="chip ${a.account_status==='active'?'good':''}">${esc(a.account_status)}</span><span class="chip">${Number(a.open_orders||0)} open orders</span><span class="chip">${Number(a.open_requests||0)} requests</span><span class="chip ${Number(a.ar_balance)>0?'warn':''}">${money(a.ar_balance)} A/R</span></div></button>`).join(''):'<div class="empty">No matching accounts.</div>';document.querySelectorAll('.account[data-id]').forEach(b=>b.onclick=()=>loadDetail(b.dataset.id))}function orderRow(x){const o=x.order||{},p=x.progress||{};return `<div class="row"><div class="rowtop"><strong>${esc(o.number||o.id)} · ${esc(o.status||'')}</strong><small>${esc(o.promisedWindowStart||o.promisedFor||'')}</small></div><div class="muted">Allocation ${Number(p.allocationPercent||0)}% · Delivery ${Number(p.deliveryPercent||0)}% · ${Number((x.batches||[]).length)} fulfillment batch(es)</div>${(x.availability?.shortages||0)>0?`<div class="chips"><span class="chip warn">${Number(x.availability.shortages)} ingredient shortage(s)</span></div>`:''}</div>`}function invoiceRow(x){const i=x.invoice||{};return `<div class="row"><div class="rowtop"><strong>${esc(i.number)} · ${money(i.total)}</strong><span class="chip ${i.status==='paid'?'good':Number(i.daysOverdue)>0?'warn':''}">${esc(i.status)}</span></div><div class="muted">Balance ${money(i.balance)} · Due ${esc(i.dueDate||'—')} ${Number(i.daysOverdue)>0?'· '+i.daysOverdue+' days overdue':''}</div></div>`}function eventRow(e){return `<div class="row"><div class="rowtop"><strong>${esc(e.title)}</strong><small>${esc(e.at)}</small></div>${e.detail?`<div class="muted">${esc(e.detail)}</div>`:''}</div>`}async function load(){const d=await api('api/wholesale-customer-360.php?action=list');rows=d.accounts||[];renderList();if(active&&rows.some(a=>a.public_id===active))await loadDetail(active)}async function loadDetail(id){active=id;renderList();const d=await api('api/wholesale-customer-360.php?action=detail&id='+encodeURIComponent(id)),x=d.detail,a=x.account,s=x.portalSummary||{};$('detail').innerHTML=`<div class="stats"><div class="stat"><small>Account</small><strong>${esc(a.account_status)}</strong></div><div class="stat"><small>A/R</small><strong>${money(s.receivables)}</strong></div><div class="stat"><small>Overdue</small><strong>${money(s.overdue)}</strong></div><div class="stat"><small>Catalog</small><strong>${Number(s.catalogItems||0)}</strong></div></div><div class="grid"><section class="section"><h2>${esc(a.business_name)}</h2><div class="muted">${esc(a.primary_email||'')} · ${esc(a.phone||'')}<br>Terms: ${esc(a.payment_terms||'—')} · Fulfillment: ${esc(a.preferred_fulfillment||'—')}<br>Price tier: ${esc(a.price_tier||'—')}</div></section><section class="section"><h2>Customer requests</h2><div class="list">${(x.requests||[]).slice(0,8).map(r=>`<div class="row"><div class="rowtop"><strong>${esc(r.subject)}</strong><span class="chip">${esc(r.status)}</span></div><div class="muted">${esc(r.request_type)} · ${esc(r.details)}</div></div>`).join('')||'<div class="empty">No requests.</div>'}</div></section><section class="section"><h2>Live orders + fulfillment</h2><div class="list">${(x.orders||[]).map(orderRow).join('')||'<div class="empty">No orders.</div>'}</div></section><section class="section"><h2>Receivables</h2><div class="list">${(x.invoices||[]).map(invoiceRow).join('')||'<div class="empty">No invoices.</div>'}</div></section><section class="section"><h2>Customer-safe history</h2><div class="list">${(x.history||[]).slice(0,20).map(eventRow).join('')||'<div class="empty">No history.</div>'}</div></section><section class="section"><h2>Pipeline / internal activity</h2><div class="list">${(x.leadActivity||[]).slice(0,20).map(r=>`<div class="row"><div class="rowtop"><strong>${esc(r.summary)}</strong><small>${esc(r.created_at)}</small></div><div class="muted">${esc(r.activity_type)}${r.details?' · '+esc(r.details):''}</div></div>`).join('')||'<div class="empty">No linked pipeline activity.</div>'}</div></section></div>`} $('search').oninput=renderList;$('refresh').onclick=()=>load().catch(e=>alert(e.message));load().catch(e=>alert(e.message));})();
</script></body></html>